"""Build a checked release in isolation; publish only after every core check passes."""
import argparse
import datetime as dt
import hashlib
import json
import math
import os
from pathlib import Path
import shutil
import subprocess
import sys
from zoneinfo import ZoneInfo
from upset_engine import apply as apply_upset_research, grade_trial

ROOT = Path(__file__).resolve().parents[1]
UTC = dt.timezone.utc


def read(path):
    return json.loads(Path(path).read_text())


def write(path, data):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, separators=(',', ':'), allow_nan=False))


def date(value):
    return dt.datetime.fromisoformat(value.replace('Z', '+00:00'))


def validate_sources(data, previous):
    refreshed = set(data['refresh']['scheduleTeamsRefreshed'])
    required = {k for k, t in previous['teams'].items() if t['conference'] != 'Non-FBS opponent'}
    missing = required - refreshed
    if missing:
        raise ValueError(f'Unrefreshed team schedules: {sorted(missing)}')
    if any('/summary?' in f['url'] for f in data['failures']):
        raise ValueError('A required game summary failed; retain the previous published release')
    games = data['games']
    if len({g['id'] for g in games}) != len(games):
        raise ValueError('Duplicate game IDs')
    old = {g['id']: g for g in previous['games']}
    for g in games:
        if g['done'] and (g['hs'] == g['as'] or min(g['hs'], g['as']) < 0):
            raise ValueError(f'Invalid completed score: {g["id"]}')
        if old.get(g['id'], {}).get('done') and not g['done']:
            raise ValueError(f'Completed result regressed: {g["id"]}')
        if g['done'] and not old.get(g['id'], {}).get('done'):
            if not g.get('stats') or not any(s.get('plays', 0) for s in g['stats'].values()):
                raise ValueError(f'New result has no usable play data: {g["id"]}')


def validate_forecasts(data, model, now):
    games = {g['id']: g for g in data['games']}
    if model['asOf'] != data['asOf'] or model['inputRetrievedAt'] != data['retrievedAt']:
        raise ValueError('Model and data snapshot do not match')
    seen = set()
    for f in model['forecasts']:
        g = games[f['id']]
        if f['id'] in seen or g['done'] or date(g['date']) <= now:
            raise ValueError(f'Forecast is duplicated, completed, or already started: {f["id"]}')
        seen.add(f['id'])
        if not all(math.isfinite(f[k]) for k in ['coreMargin', 'coreTotal', 'coreSd', 'margin', 'total', 'sd']):
            raise ValueError('Nonfinite forecast')
        if min(f['coreSd'], f['sd']) <= 0:
            raise ValueError('Invalid forecast uncertainty')
        trial = f.get('upsetResearch')
        if trial and trial.get('status') == 'testing':
            if trial.get('appliedToMain') is not False or trial['baselineHomeMargin'] != f['coreMargin']:
                raise ValueError('Research forecast changed the main baseline')
            if not all(math.isfinite(trial[k]) for k in ['candidateHomeMargin', 'candidateSd', 'candidateHomeWin']):
                raise ValueError('Nonfinite research forecast')
            if trial['candidateSd'] <= 0 or not 0 <= trial['candidateHomeWin'] <= 1:
                raise ValueError('Invalid research uncertainty')
            expected = f['coreMargin'] + sum(c['homeMarginPoints'] for c in trial['contributions'])
            if abs(expected - trial['candidateHomeMargin']) > 1e-8:
                raise ValueError('Research contributions do not match its forecast')


def snapshot(data, model, quotes, recorded_at, recovered=False):
    ids = {f['id'] for f in model['forecasts']}
    return {'generatedAt': model['generatedAt'], 'recordedAt': recorded_at,
            'type': 'recovered_saved_forecast' if recovered else 'prospective_snapshot',
            'asOf': model.get('asOf', data['asOf']), 'forecasts': model['forecasts'],
            'games': {g['id']: g for g in data['games'] if g['id'] in ids},
            'quotes': {k: v for k, v in quotes.get('games', {}).items() if k in ids}}


def grade(edge, actual):
    if abs(edge) < 1e-9:
        return 'no_pick'
    if abs(actual) < 1e-9:
        return 'push'
    return 'win' if (edge > 0) == (actual > 0) else 'loss'


def pick_explanation(f, g, picked, data):
    """Explain saved model inputs separately from observed game outcomes."""
    labels = {
        'Elo difference': 'overall team strength',
        'Net success-rate difference': 'sustaining drives and forcing stops',
        'Scoring margin difference': 'earlier scoring margins',
        'Scoring environment': 'the scoring patterns of the two teams',
        'Home field': 'home field',
        'Explosive-rate difference': 'big-play production',
        'Yards/game difference': 'offensive yardage',
    }
    if not picked:
        return {'pregame': 'The main forecast did not select a winner.', 'recap': [], 'drivers': []}
    sign = 1 if picked == g['home'] else -1
    team_name = lambda t: data.get('teams', {}).get(t, {}).get('name', t)
    opponent = g['away'] if sign == 1 else g['home']
    drivers = sorted([{'factor': labels.get(c['name'], c['name']),
                       'pointsTowardPick': round(sign * c['points'], 2)}
                      for c in f.get('coreContributions', [])],
                     key=lambda c: c['pointsTowardPick'], reverse=True)
    support = [c for c in drivers if c['pointsTowardPick'] >= .2][:2]
    reasons = ' and '.join(c['factor'] for c in support)
    margin = abs(f['coreMargin'])
    lean = 'This was a very small lean' if margin < 1 else 'This was a close call' if margin < 3 else 'The saved forecast favored this team'
    pregame = f'{lean}: {team_name(picked)} by {margin:.1f} points.'
    pregame += f' The strongest supporting inputs were {reasons}.' if support else ' The starting value and combined inputs produced the pick; no strong individual advantage was saved.'
    baseline = sign * f.get('coreIntercept', 0)
    if baseline > max([c['pointsTowardPick'] for c in support] or [0]):
        pregame += ' The model’s starting value also contributed more than any single supporting team statistic.'
    stats = g.get('stats') or {}
    a, b = stats.get(picked, {}), stats.get(opponent, {})
    def number(side, key):
        try:
            return float(side.get('boxscore', {}).get(key, side.get(key)))
        except (ValueError, TypeError):
            return None
    recap = []
    ta, tb = number(a, 'turnovers'), number(b, 'turnovers')
    if ta is not None and tb is not None and ta < tb:
        recap.append(f'{team_name(picked)} gave the ball away {int(ta)} times; {team_name(opponent)} did so {int(tb)} times.')
    ya, yb = number(a, 'totalYards'), number(b, 'totalYards')
    if ya is not None and yb is not None and ya > yb:
        recap.append(f'{team_name(picked)} gained {int(ya)} yards to {team_name(opponent)}’s {int(yb)}.')
    try:
        ca, aa = map(int, a['boxscore']['thirdDownEff'].split('-'))
        cb, ab = map(int, b['boxscore']['thirdDownEff'].split('-'))
        if aa and ab and ca / aa > cb / ab:
            recap.append(f'{team_name(picked)} converted {ca} of {aa} third downs; {team_name(opponent)} converted {cb} of {ab}.')
    except (KeyError, ValueError, ZeroDivisionError):
        pass
    recap = recap[:2]
    if ya is not None and yb is not None and ya < yb:
        recap.append(f'{team_name(picked)} was outgained {int(yb)}–{int(ya)}, so the win was not a clean sweep of the underlying stats.')
    if not recap:
        recap.append('The final score confirms the outcome. The saved box score does not provide enough evidence for a more specific game recap.')
    return {'pregame': pregame, 'recap': recap, 'drivers': drivers,
            'baselineTowardPick': round(baseline, 2), 'scope': 'Pregame reasons use only the saved main-model forecast. Game recap uses the final box score; it does not prove causation.'}


def grade_snapshots(snapshots, data):
    selected = {}
    completed = {g['id']: g for g in data['games'] if g['done']}
    for snap in sorted(snapshots, key=lambda x: x['generatedAt']):
        for f in snap['forecasts']:
            g = completed.get(f['id'])
            original = snap['games'].get(f['id'])
            if not g or not original:
                continue
            kickoff = min(date(original['date']), date(g['date']))
            if date(snap['generatedAt']) >= kickoff:
                continue
            if original.get('done'):
                continue
            q = snap['quotes'].get(f['id'], {})
            # Do not attach a closing or postgame line to an earlier prediction.
            quote_ok = q.get('retrievedAt') and date(q['retrievedAt']) < kickoff
            spread = q.get('homeSpread') if quote_ok else None
            total = q.get('overUnder') if quote_ok else None
            actual = g['hs'] - g['as']
            picked = g['home'] if f['coreMargin'] > 0 else g['away'] if f['coreMargin'] < 0 else None
            picked_underdog = bool(picked and spread not in (None, 0) and f['coreMargin'] * spread > 0)
            explanation = pick_explanation(f, g, picked, data) if picked_underdog else None
            sd = f.get('coreSd')
            probability = .5 * (1 + math.erf(abs(f['coreMargin']) / (sd * math.sqrt(2)))) if sd and sd > 0 else None
            selected[g['id']] = {
                'id': g['id'], 'date': g['date'], 'home': g['home'], 'away': g['away'],
                'homeScore': g['hs'], 'awayScore': g['as'], 'forecastAt': snap['generatedAt'],
                'archiveType': snap['type'], 'predictedHomeMargin': f['coreMargin'],
                'predictedTotal': f['coreTotal'], 'homeSpread': spread, 'overUnder': total,
                'quoteRetrievedAt': q.get('retrievedAt') if quote_ok else None,
                'winner': grade(f['coreMargin'], actual),
                'spread': grade(f['coreMargin'] + spread, actual + spread) if spread is not None else 'unavailable',
                'total': grade(f['coreTotal'] - total, g['hs'] + g['as'] - total) if total is not None else 'unavailable',
                'homeUnderdog': spread > 0 if spread is not None else None,
                'upset': grade(-spread, actual) == 'loss' if spread not in (None, 0) else None,
                'pickedTeam': picked, 'pickedUnderdog': picked_underdog,
                'pickWinProbability': probability, 'neutral': g.get('neutral', False),
                'upsetPickResult': grade(f['coreMargin'], actual) if picked_underdog else 'not_picked',
                'explanation': explanation, 'sourceUrl': g.get('url'), 'quoteProvider': q.get('provider') if quote_ok else None,
                'sourceArchive': 'forecast-archive/' + snap.get('asOf', snap['generatedAt'][:10]) + '-' + hashlib.sha256(snap['generatedAt'].encode()).hexdigest()[:16] + '.json',
            }
    rows = sorted(selected.values(), key=lambda r: r['date'], reverse=True)
    counts = {k: {s: sum(r[k] == s for r in rows) for s in ['win', 'loss', 'push', 'no_pick', 'unavailable']}
              for k in ['winner', 'spread', 'total']}
    counts['upset'] = {s: sum(r['upsetPickResult'] == s for r in rows) for s in ['win', 'loss', 'push']}
    return {'generatedAt': dt.datetime.now(UTC).isoformat(), 'games': rows, 'records': counts,
            'method': 'Latest saved forecast before kickoff, paired with a line retrieved before kickoff. Recovered legacy snapshots are identified. No reconstructed predictions are counted as issued picks.'}


def make_odds(work, model, data):
    games = {g['id']: g for g in data['games']}
    rows = {}
    for f in model['forecasts']:
        g = games[f['id']]
        p = ROOT / '.current-cache' / f'summary-{g["id"]}.json'
        if not p.exists():
            continue
        cached = read(p)
        x = cached['data']
        comp = x.get('header', {}).get('competitions', [{}])[0]
        offers = sorted(x.get('pickcenter', []), key=lambda x: x.get('provider', {}).get('priority', 99))
        offer = next((o for o in offers if all(isinstance(o.get(s+'TeamOdds', {}).get('moneyLine'), (int, float)) for s in ['home', 'away'])), None)
        if offer:
            rows[g['id']] = {'id': g['id'], 'date': g['date'], 'state': comp.get('status', {}).get('type', {}).get('state'),
                            'timeValid': g['timeValid'], 'retrievedAt': cached['retrievedAt'], 'url': g['url'],
                            'provider': offer.get('provider', {}).get('name'), 'channels': [],
                            'homeMoneyline': offer['homeTeamOdds']['moneyLine'], 'awayMoneyline': offer['awayTeamOdds']['moneyLine']}
    return {'retrievedAt': data['retrievedAt'], 'modelAsOf': data['asOf'], 'games': rows}


def run():
    parser = argparse.ArgumentParser()
    parser.add_argument('--as-of', default=dt.datetime.now(ZoneInfo('America/New_York')).date().isoformat())
    args = parser.parse_args()
    today = dt.datetime.now(ZoneInfo('America/New_York')).date().isoformat()
    if args.as_of != today:
        raise ValueError('Production refresh must use the current Eastern date; historical replays need a separate path')
    now = dt.datetime.now(UTC)
    run_id = now.strftime('%Y%m%dT%H%M%SZ')
    work = ROOT / '.refresh-work' / run_id
    work.mkdir(parents=True)
    seeds = ['data.json', 'model.json', 'game-details.json', 'history.json', 'research-notes.json', 'context-history-inputs.json']
    for name in seeds:
        shutil.copy2(ROOT/name, work/name)
    if (ROOT/'upset-metric-history.json').exists():
        shutil.copy2(ROOT/'upset-metric-history.json', work/'upset-metric-history.json')
    old_data, old_model, old_quotes = (read(work/n) for n in seeds[:3])
    env = dict(os.environ, DART_DATA_ROOT=str(work), DART_DATA_DIR=str(work),
               DART_MODEL_INPUT=str(work/'data.json'), DART_MODEL_OUTPUT=str(work/'model.json'),
               DART_HISTORY_CACHE=str(ROOT/'.current-cache'))

    def execute(script, *arguments):
        print('RUN', script, flush=True)
        subprocess.run([sys.executable, str(ROOT/'scripts'/script), *arguments], env=env, cwd=ROOT, check=True, timeout=1800)

    execute('refresh_core.py', '--as-of', args.as_of)
    data = read(work/'current-data.json')
    validate_sources(data, old_data)
    write(work/'data.json', data)
    shutil.copy2(work/'current-game-details.json', work/'game-details.json')
    execute('coach_changes.py')
    execute('model.py')
    model = read(work/'model.json')
    validate_forecasts(data, model, dt.datetime.now(UTC))
    # Keep the full expanding-date errors for the new research fit before
    # restoring the intentionally frozen public benchmark below.
    research_heldout = model['heldout']
    # Keep the original benchmark immutable; current replay metrics are separate.
    replay = {k: model[k] for k in ['core', 'full', 'testedGames', 'testStart', 'testEnd']}
    for key in ['core', 'full', 'heldout', 'calibration', 'testedGames', 'testStart', 'testEnd']:
        model[key] = old_model[key]
    model['evaluationFrozenThrough'] = old_model.get('evaluationFrozenThrough', old_model['testEnd'])
    model['latestReplay'] = replay
    model['refreshRunId'] = run_id
    write(work/'model.json', model)
    execute('matchup_context.py', '--data-file', 'data.json')
    execute('availability.py')
    execute('sportsdataio_check.py')
    execute('matchup_environment.py')
    availability = read(work/'availability.json')
    for f in model['forecasts']:
        row = availability['games'].get(f['id'], {})
        qb = [p for side in ['home', 'away'] for p in (row.get(side) or {}).get('concerns', []) if p['unit'] == 'Quarterback']
        f['availabilityStatus'] = row.get('status', 'not_reported')
        f['reviewRequired'] = bool(qb)
        f['lineupWatch'] = [p['name'] + ': ' + p['status'] for p in qb]
    execute('upset_engine.py', '--collect')
    frozen_heldout = model['heldout']
    model['heldout'] = research_heldout
    apply_upset_research(data, model, read(work/'upset-metric-history.json'), availability)
    model['heldout'] = frozen_heldout
    write(work/'model.json', model)
    write(work/'parlay-odds.json', make_odds(work, model, data))
    execute('sniper_props.py')
    # Preserve all completed games in the history browser.
    history = read(work/'history.json')
    merged = {g['id']: g for g in history['games']}
    merged.update({g['id']: g for g in data['games'] if g['done']})
    history['games'] = sorted(merged.values(), key=lambda g: g['date'])
    history['asOf'] = args.as_of
    write(work/'history.json', history)
    archive = ROOT/'forecast-archive'
    snaps = [read(p) for p in archive.glob('*.json')]
    recovered = snapshot(old_data, old_model, old_quotes, now.isoformat(), recovered=True)
    if not any(s['generatedAt'] == recovered['generatedAt'] for s in snaps):
        snaps.append(recovered)
    current = snapshot(data, model, read(work/'game-details.json'), dt.datetime.now(UTC).isoformat())
    snaps.append(current)
    write(work/'daily-results.json', grade_snapshots(snaps, data))
    write(work/'upset-research-results.json', grade_trial(snaps, data))
    context = read(work/'matchup-context.json')
    status = {'runId': run_id, 'status': 'validated', 'dataAsOf': data['asOf'],
              'lastSuccessfulRefresh': dt.datetime.now(UTC).isoformat(), 'staleAfterHours': 30,
              'scheduleTeams': len(data['refresh']['scheduleTeamsRefreshed']), 'forecastGames': len(model['forecasts']),
              'availability': availability['coverage'], 'supplementalInjuryCheck': availability['supplementalCheck'], 'coachChangeTrial': model.get('coachChangeTrial'), 'sourceWarnings': availability['failures'] + context['fetchFailures'] + read(work/'coach-change-history.json')['fetchFailures'],
              'upsetResearchTrial': model.get('upsetResearchTrial'),
              'modelLimit': 'Protection, run resistance and touchdown drives now feed a separate experimental forecast. Main picks are unchanged. Starting roles, injury effects and weather are not fitted. Reported QB concerns exclude a game from automated tickets.'}

    write(work/'refresh-status.json', status)
    validate_forecasts(data, model, dt.datetime.now(UTC))
    # No repository data is replaced until the release passes the checks above.
    publish = ['data.json', 'model.json', 'game-details.json', 'history.json', 'current-data.json',
               'current-game-details.json', 'latest-results.json', 'matchup-context.json', 'availability.json',
               'matchup-environment.json', 'coach-change-history.json', 'context-history-inputs.json', 'parlay-odds.json', 'sniper-props.json', 'daily-results.json', 'refresh-status.json',
               'upset-metric-history.json', 'upset-research-results.json']
    for name in publish:
        read(work/name)  # Every output must exist and parse.
    for snap in [recovered, current]:
        key = hashlib.sha256(snap['generatedAt'].encode()).hexdigest()[:16]
        destination = archive/(snap['asOf']+'-'+key+'.json')
        if not destination.exists():
            write(destination, snap)
    for name in publish:
        shutil.copy2(work/name, ROOT/name)
    print(json.dumps(status, indent=2), flush=True)


if __name__ == '__main__':
    try:
        run()
    except Exception as error:
        write(ROOT/'refresh-failure.json', {'failedAt': dt.datetime.now(UTC).isoformat(), 'error': str(error)})
        raise

"""Prospective upset research: source-backed matchup inputs and a shadow model.

No narrative bonuses or changes to production core forecasts. Historical feature
reconstruction is development evidence, never an issued-pick record.
"""
import argparse
import concurrent.futures
import datetime as dt
import json
import math
import os
from pathlib import Path

import numpy as np
from refresh_core import get, BASE

ROOT = Path(__file__).resolve().parents[1]
VERSION = 'upset-research-v1'
METRIC_VERSION = 1
MIN_TRAIN = 60
LABELS = ['Protection matchup', 'Run-game resistance', 'Touchdown drives']
PASS = {'Pass Reception', 'Pass Incompletion', 'Passing Touchdown', 'Sack',
        'Interception', 'Pass Interception Return'}
RUN = {'Rush', 'Rushing Touchdown'}


def date(s):
    if not isinstance(s, str):
        raise ValueError('Missing timestamp')
    parsed = dt.datetime.fromisoformat(s.replace('Z', '+00:00'))
    if parsed.tzinfo is None:
        raise ValueError('Timestamp needs a timezone')
    return parsed


def stamp():
    return dt.datetime.now(dt.timezone.utc).isoformat()


def read(path, default=None):
    return json.loads(path.read_text()) if path.exists() else default


def write(path, value):
    path.write_text(json.dumps(value, separators=(',', ':'), allow_nan=False))


def extract(summary, game, observed):
    """Count regulation dropbacks, runs and offensive drives; no text inference."""
    competition = (summary.get('header', {}).get('competitions') or [{}])[0]
    if str(summary.get('header', {}).get('id', game['id'])) != str(game['id']):
        return None
    if not competition.get('status', {}).get('type', {}).get('completed'):
        return None
    competitors = {str(x.get('id')) for x in competition.get('competitors', [])}
    if competitors != {str(game['home']), str(game['away'])}:
        return None
    rows = {t: dict(passPlays=0, sacks=0, runs=0, stuffed=0, drives=0, touchdowns=0)
            for t in [game['home'], game['away']]}
    seen_plays, seen_drives = set(), set()
    for drive in summary.get('drives', {}).get('previous', []):
        did = drive.get('id')
        if did and did in seen_drives:
            continue
        if did:
            seen_drives.add(did)
        offense = str(drive.get('team', {}).get('id', ''))
        drive_plays = []
        for p in drive.get('plays', []):
            pid = p.get('id')
            if pid and pid in seen_plays:
                continue
            if pid:
                seen_plays.add(pid)
            kind = p.get('type', {}).get('text')
            start = p.get('start', {})
            team = str(start.get('team', {}).get('id', ''))
            text = p.get('text', '').lower()
            if (kind not in PASS | RUN or p.get('isPenalty') or team not in rows
                    or start.get('down') not in (1, 2, 3, 4)
                    or p.get('period', {}).get('number', 1) > 4
                    or 'kneel' in text or 'spike' in text):
                continue
            row = rows[team]
            if kind in PASS:
                row['passPlays'] += 1
                row['sacks'] += int(kind == 'Sack')
            else:
                row['runs'] += 1
                row['stuffed'] += int(p.get('statYardage', 0) <= 0)
            if team == offense:
                drive_plays.append(p)
        # A kneel-only possession is not a scoring opportunity. TD requires an
        # offensive TD play; a pick-six at the end is not credited to the offense.
        if offense in rows and drive_plays:
            rows[offense]['drives'] += 1
            rows[offense]['touchdowns'] += int(any(
                p.get('type', {}).get('text') in {'Passing Touchdown', 'Rushing Touchdown'}
                and not p.get('isTurnover') for p in drive_plays))
    if not all(r['passPlays'] + r['runs'] >= 10 and r['drives'] >= 3 for r in rows.values()):
        return None
    return {'id': game['id'], 'date': game['date'], 'season': game['season'],
            'home': game['home'], 'away': game['away'], 'teams': rows,
            'schemaVersion': METRIC_VERSION, 'sourceUrl': BASE + 'summary?event=' + game['id'],
            'observedAt': observed, 'method': 'Regulation only; sacks are a pressure proxy; TDs per offensive drive, not red-zone efficiency.'}


def collect(data, existing, cache, workers=8):
    season = int(data['asOf'][:4])
    games = [g for g in data['games'] if g['done'] and g['season'] == season
             and g['date'][:10] <= data['asOf']]
    saved = (existing or {}).get('games', {})
    output, failures = {}, []

    def one(g):
        old = saved.get(g['id'])
        if (old and old.get('schemaVersion') == METRIC_VERSION
                and all(old.get(k) == g[k] for k in ['date', 'home', 'away', 'season'])):
            return g['id'], old, None
        cached = read(cache / ('summary-' + g['id'] + '.json'), {})
        if cached.get('retrievedAt') and (row := extract(cached.get('data', cached), g, cached['retrievedAt'])):
            return g['id'], row, None
        raw, error = get(BASE + 'summary?event=' + g['id'])
        row = extract(raw, g, stamp()) if raw else None
        return g['id'], row, error or (None if row else 'Incomplete or mismatched play-by-play')

    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
        for index, (gid, row, error) in enumerate(pool.map(one, games), 1):
            if row:
                output[gid] = row
            else:
                failures.append({'id': gid, 'error': error})
            if index % 100 == 0:
                print(f'Play metrics: {index}/{len(games)} checked, {len(failures)} unavailable', flush=True)
    return {'schemaVersion': METRIC_VERSION, 'generatedAt': stamp(), 'asOf': data['asOf'],
            'games': output, 'coverage': {'completedGames': len(games), 'usableGames': len(output)},
            'failures': failures}


def profile(team, game, metrics, cutoff):
    totals = {s: dict(passPlays=0, sacks=0, runs=0, stuffed=0, drives=0, touchdowns=0)
              for s in ['offense', 'defense']}
    sources = []
    for row in metrics['games'].values():
        if (row['season'] != game['season'] or row['date'][:10] >= game['date'][:10]
                or date(row['date']) >= cutoff or row['id'] == game['id']
                or team not in [row['home'], row['away']]):
            continue
        opponent = row['away'] if row['home'] == team else row['home']
        for side, tid in [('offense', team), ('defense', opponent)]:
            for key in totals[side]:
                totals[side][key] += row['teams'][tid][key]
        sources.append({k: row[k] for k in ['id', 'date', 'sourceUrl', 'observedAt']})
    ready = len(sources) >= 3 and all(r['passPlays'] >= 60 and r['runs'] >= 60 and r['drives'] >= 20 for r in totals.values())
    rates = {}
    for side, r in totals.items():
        rates[side] = {
            'sackRate': r['sacks'] / r['passPlays'] if r['passPlays'] else None,
            'stuffRate': r['stuffed'] / r['runs'] if r['runs'] else None,
            'rushShare': r['runs'] / (r['runs'] + r['passPlays']) if r['runs'] + r['passPlays'] else None,
            'tdDriveRate': r['touchdowns'] / r['drives'] if r['drives'] else None}
    return {'teamId': team, 'ready': ready, 'games': len(sources), 'counts': totals,
            **rates, 'sources': sources}


def features(game, metrics, cutoff):
    h, a = [profile(game[s], game, metrics, cutoff) for s in ['home', 'away']]
    if not h['ready'] or not a['ready']:
        return None, h, a
    ho, hd, ao, ad = h['offense'], h['defense'], a['offense'], a['defense']
    values = [10000 * (ao['sackRate'] * hd['sackRate'] - ho['sackRate'] * ad['sackRate']),
              100 * (ao['rushShare'] * hd['stuffRate'] - ho['rushShare'] * ad['stuffRate']),
              100 * (ho['tdDriveRate'] + ad['tdDriveRate'] - ao['tdDriveRate'] - hd['tdDriveRate'])]
    return values, h, a


def fit(rows):
    x = np.array([r['x'] for r in rows]); y = np.array([r['actual'] - r['baseline'] for r in rows])
    mean, scale = x.mean(0), x.std(0)
    scale[scale < 1e-8] = 1
    z = (x - mean) / scale
    # No intercept: this experiment tests new matchup information, not a new
    # global home-field offset. Fixed ridge penalty, no tuning on the casebook.
    beta = np.linalg.solve(z.T @ z + 30 * np.eye(len(LABELS)), z.T @ y)
    return mean, scale, beta


def adjustments(fitted, values):
    mean, scale, beta = fitted
    return ((np.array(values) - mean) / scale * beta).tolist()


def probability(margin, sd):
    return .5 * (1 + math.erf(margin / (sd * math.sqrt(2))))


def lineup(game, availability, observed):
    raw = availability.get('games', {}).get(game['id'], {})
    sides = {}
    for side in ['home', 'away']:
        row = raw.get(side) or {}
        try:
            checked = date(row['retrievedAt']); published = date(row['publishedAt'])
            valid = (raw.get('status') == 'reported' and row.get('status') == 'reported'
                     and row.get('teamId') == game[side] and row.get('gameDate') == game['date'][:10]
                     and row.get('opponent') == game['away' if side == 'home' else 'home']
                     and published <= checked <= observed < date(game['date'])
                     and (observed - checked).total_seconds() <= 48 * 3600)
        except (KeyError, ValueError, TypeError):
            valid = False
        concerns = [{k: p.get(k) for k in ['name', 'position', 'unit', 'status']}
                    for p in row.get('concerns', []) if p.get('unit') in ['Quarterback', 'Center', 'Offensive line']] if valid else []
        sides[side] = {'status': 'reported' if valid else 'unknown', 'concerns': concerns,
                       'sourceUrl': row.get('sourceUrl') if valid else None,
                       'observedAt': row.get('retrievedAt') if valid else None,
                       'publishedAt': row.get('publishedAt') if valid else None,
                       'startingRoles': 'unknown'}
    return sides


def apply(data, model, metrics, availability, now=None):
    """Fit only against expanding-date baseline errors; never use current injuries
    in historical rows. The saved old core/full evaluation stays untouched.
    """
    now = now or dt.datetime.now(dt.timezone.utc)
    byid = {g['id']: g for g in data['games']}
    records = []
    for r in model.get('heldout', []):
        g = byid.get(r['id'])
        if not g or not g['done'] or date(g['date']) >= now:
            continue
        values, _, _ = features(g, metrics, date(g['date']))
        if values is not None:
            records.append({'id': r['id'], 'date': g['date'], 'x': values,
                            'baseline': r['core'][0], 'actual': r['actual'][0], 'sd': r['coreSd']})
    replay = []
    for day in sorted({r['date'][:10] for r in records}):
        earlier = [r for r in records if r['date'][:10] < day]
        if len(earlier) < MIN_TRAIN:
            continue
        fitted = fit(earlier)
        for r in records:
            if r['date'][:10] == day:
                replay.append({**{k: r[k] for k in ['id', 'date', 'baseline', 'actual', 'sd']},
                               'candidate': r['baseline'] + sum(adjustments(fitted, r['x']))})
    fitted = fit(records) if len(records) >= MIN_TRAIN else None
    ready = 0
    for f in model['forecasts']:
        g = byid[f['id']]
        values, h, a = features(g, metrics, min(now, date(model['inputRetrievedAt'])))
        covered = fitted is not None and values is not None and now < date(g['date']) and not g['done']
        parts = adjustments(fitted, values) if covered else []
        margin = f['coreMargin'] + sum(parts) if covered else None
        teams = data['teams']; name = lambda t: teams.get(t, {}).get('name', t)
        lineups = lineup(g, availability, now)
        missing = ['Confirmed starting QB, replacement experience and starting offensive-line roles are not yet connected.']
        if not h['ready'] or not a['ready']:
            missing.append('Insufficient play-by-play sample for a matchup adjustment.')
        if fitted is None:
            missing.append(f'Need {MIN_TRAIN} usable earlier-game residuals; have {len(records)}.')
        for side in ['home', 'away']:
            if lineups[side]['status'] == 'unknown':
                missing.append(f'{name(g[side])}: no fresh, verified availability report for this game.')
        facts = []
        for own, opponent in [(h, a), (a, h)]:
            if own['ready'] and opponent['ready']:
                facts += [
                    f"{name(own['teamId'])} allowed sacks on {own['offense']['sackRate']:.1%} of counted dropbacks; {name(opponent['teamId'])} sacked opponents on {opponent['defense']['sackRate']:.1%}.",
                    f"{name(own['teamId'])} ran on {own['offense']['rushShare']:.1%} of counted plays; {name(opponent['teamId'])} stopped {opponent['defense']['stuffRate']:.1%} of opponents’ runs for no gain or a loss.",
                    f"{name(own['teamId'])} scored a touchdown on {own['offense']['tdDriveRate']:.1%} of counted drives; {name(opponent['teamId'])} allowed touchdowns on {opponent['defense']['tdDriveRate']:.1%}." ]
        research = {'version': VERSION, 'generatedAt': now.isoformat(), 'status': 'testing' if covered else 'insufficient_data',
                    'appliedToMain': False, 'baselineHomeMargin': f['coreMargin'],
                    'candidateHomeMargin': margin, 'candidateSd': f['coreSd'] if covered else None,
                    'candidateHomeWin': probability(margin, f['coreSd']) if covered else None,
                    'contributions': [{'name': label, 'homeMarginPoints': value} for label, value in zip(LABELS, parts)],
                    'profiles': {'home': h, 'away': a}, 'lineup': lineups, 'facts': facts, 'missing': missing,
                    'reviewRequired': any(s['status'] == 'unknown' or s['concerns'] for s in lineups.values()),
                    'limit': 'Experimental matchup adjustment. Starting-role changes have no fitted numerical effect. Sack and run rates are not independently opponent-adjusted; the baseline already includes team strength. TDs per drive are not red-zone efficiency. Rest, rivalry, travel and crowd narratives add no automatic points.'}
        f['upsetResearch'] = research
        ready += int(covered)
    summary = {'version': VERSION, 'status': 'testing', 'appliedToMain': False,
               'trainingRows': len(records), 'forecastGames': len(model['forecasts']), 'coveredForecasts': ready,
               'metricCoverage': metrics['coverage'], 'historicalReplay': {
                   'games': len(replay), 'type': 'development_replay',
                   'baselineMarginMAE': sum(abs(r['baseline'] - r['actual']) for r in replay) / len(replay) if replay else None,
                   'candidateMarginMAE': sum(abs(r['candidate'] - r['actual']) for r in replay) / len(replay) if replay else None,
                   'note': 'Earlier-date residual training; same games for both models. Reconstructed inputs were retrieved later. Casebook games may be included; this is development evidence, not independent proof or issued picks.'},
               'method': 'Ridge penalty 30 on three standardized matchup features, fitted to expanding-date core-margin residuals. Minimum 60 earlier residuals. Core uncertainty retained; no manual injury penalty. No automatic promotion.'}
    model['upsetResearchTrial'] = summary
    return summary


def grade_trial(snapshots, data):
    """Only actually recorded pre-kickoff candidate/base pairs count."""
    completed = {g['id']: g for g in data['games'] if g['done']}
    chosen = {}
    for snap in sorted(snapshots, key=lambda s: s.get('recordedAt', '')):
        if snap.get('type') != 'prospective_snapshot':
            continue
        for f in snap['forecasts']:
            r = f.get('upsetResearch') or {}; g = completed.get(f['id']); original = snap['games'].get(f['id'])
            if r.get('version') != VERSION or r.get('status') != 'testing' or not g or not original or original.get('done'):
                continue
            try:
                cutoff = min(date(original['date']), date(g['date']))
                if not date(r['generatedAt']) <= date(snap['recordedAt']) < cutoff or date(snap['generatedAt']) >= cutoff:
                    continue
                baseline, candidate, sd = f['coreMargin'], r['candidateHomeMargin'], r['candidateSd']
                if not all(math.isfinite(v) for v in [baseline, candidate, sd]) or sd <= 0:
                    continue
            except (KeyError, TypeError, ValueError):
                continue
            actual = g['hs'] - g['as']; target = int(actual > 0)
            q = snap.get('quotes', {}).get(f['id'], {})
            try:
                spread = q.get('homeSpread') if date(q['retrievedAt']) <= date(snap['recordedAt']) < cutoff else None
            except (KeyError, TypeError, ValueError):
                spread = None
            row = {'id': g['id'], 'date': g['date'], 'recordedAt': snap['recordedAt'],
                   'version': VERSION, 'actualHomeMargin': actual, 'homeSpread': spread}
            for label, margin in [('baseline', baseline), ('candidate', candidate)]:
                upset = isinstance(spread, (int, float)) and spread != 0 and margin * spread > 0
                row[label] = {'homeMargin': margin, 'absoluteError': abs(margin - actual),
                              'brier': (probability(margin, sd) - target) ** 2,
                              'winner': 'no_pick' if margin == 0 else 'win' if (margin > 0) == (actual > 0) else 'loss',
                              'pickedUnderdog': upset}
            chosen[g['id']] = row
    rows = list(chosen.values()); summary = {}
    for label in ['baseline', 'candidate']:
        summary[label] = {'games': len(rows),
                         'marginMAE': sum(r[label]['absoluteError'] for r in rows) / len(rows) if rows else None,
                         'brier': sum(r[label]['brier'] for r in rows) / len(rows) if rows else None,
                         'winnerRecord': {s: sum(r[label]['winner'] == s for r in rows) for s in ['win', 'loss', 'no_pick']},
                         'upsetRecord': {s: sum(r[label]['pickedUnderdog'] and r[label]['winner'] == s for r in rows) for s in ['win', 'loss']}}
    return {'version': VERSION, 'generatedAt': stamp(), 'games': sorted(rows, key=lambda r: r['date'], reverse=True),
            'summary': summary, 'method': 'Latest prospectively recorded pre-kickoff pair per game. Includes losses and games with no adjustment. Recovered files and reconstructed historical trials excluded. No profit claim.'}


def main():
    parser = argparse.ArgumentParser(); parser.add_argument('--collect', action='store_true'); args = parser.parse_args()
    root = Path(os.environ.get('DART_DATA_ROOT', str(ROOT)))
    data = read(root / 'data.json')
    if args.collect:
        cache = Path(os.environ.get('DART_HISTORY_CACHE', str(ROOT / '.current-cache')))
        metrics = collect(data, read(root / 'upset-metric-history.json', {}), cache)
        write(root / 'upset-metric-history.json', metrics); print(json.dumps(metrics['coverage']), flush=True)
    else:
        model = read(root / 'model.json')
        summary = apply(data, model, read(root / 'upset-metric-history.json'), read(root / 'availability.json', {}))
        write(root / 'model.json', model); print(json.dumps(summary), flush=True)


if __name__ == '__main__':
    main()

